from django.core.exceptions import ValidationError
from django.db import IntegrityError
from django.shortcuts import redirect, render
from .models import Categoria, Libro


def guardar_datos_libro(request, libro):
    libro.nombre = request.POST.get('nombre', '').strip()
    libro.codigo_isbn = request.POST.get('codigo_isbn', '').strip()
    libro.descripcion = request.POST.get('descripcion', '').strip()

    try:
        libro.categoria_id = int(request.POST.get('categoria', ''))
    except ValueError:
        raise ValidationError('Selecciona una categoría válida.')

    if 'imagen' in request.FILES:
        libro.imagen = request.FILES['imagen']

    libro.full_clean()
    libro.save()


def crear_libro(request):
    libro = Libro()
    error = None

    if request.method == 'POST':
        try:
            guardar_datos_libro(request, libro)
            return redirect('listado_libros')
        except ValidationError as exc:
            error = ' '.join(exc.messages)
        except IntegrityError:
            error = 'No se pudo guardar el libro. Revisa el ISBN y la categoría.'

    return render(request, 'biblioteca/formulario.html', {
        'libro': libro,
        'categorias': Categoria.objects.order_by('nombre'),
        'error': error,
    })

