def eliminar_libro(request, pk):
    libro = get_object_or_404(Libro, pk=pk)
    if request.method == 'POST':
        libro.delete()
        return redirect('listado_libros')
    return render(request, 'biblioteca/confirmar_eliminar.html', {'libro': libro})

